class Solution {
    public int numberOfSteps(int num) {
        int steps = 0;
        while (num > 0) {
            if (num % 2 == 0) {
                num /= 2;
            } else {
                num--;
            }
            steps++;
        }
        return steps;
    }
}

class Solution {
    public int numberOfSteps(int num) {
        if (num == 0) {
            return 0;
        }

        int steps = 0;
        while (num > 0) {
            steps += 1;
            if ((num & 1) == 1) {
                steps += 1;
            }
            num >>= 1;
        }
        return steps - 1;
    }
}

class Solution {
    public int numberOfSteps(int num) {
        if (num == 0) {
            return 0;
        }

        int bitLength = Integer.SIZE - Integer.numberOfLeadingZeros(num);
        int setBits = Integer.bitCount(num);
        return bitLength + setBits - 1;
    }
}

class Solution {
    public int numberOfSteps(int num) {
        if (num == 0) {
            return 0;
        }
        if ((num & 1) == 0) {
            return 1 + numberOfSteps(num / 2);
        }
        return 1 + numberOfSteps(num - 1);
    }
}
